@import url('https://fonts.googleapis.com/css2?family=Onest:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Facebook DNA — feed gray, white cards, the blue, dense social chrome */
.theme-facebook-dna {
  --bg: oklch(0.960 0.005 258.3);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.921 0.008 260.7);
  --fg: oklch(0.115 0 0);
  --fg-muted: oklch(0.513 0.007 264.5);
  --accent: oklch(0.564 0.240 261.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.687 0.204 140.7);
  --line: oklch(0.896 0.006 255.5);
  --success: oklch(0.687 0.204 140.7);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.645 0.228 25.1);
  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Onest", "Helvetica Neue", sans-serif;
  --font-body: "Onest", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-facebook-dna h1,
.theme-facebook-dna h2,
.theme-facebook-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-facebook-dna { --font-ui: var(--font-display); }
.theme-facebook-dna h1 { font-weight: 700; letter-spacing: -0.02em; }
.theme-facebook-dna button { font-weight: 600; }

/* depth */
.theme-facebook-dna thead th { font-size: 0.8em; font-weight: 700; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-facebook-dna td { border-bottom: 1px solid var(--line); }
.theme-facebook-dna tbody tr:hover { background: oklch(0.94 0.01 258); }
.theme-facebook-dna a { color: var(--accent); font-weight: 600; text-decoration: none; }
.theme-facebook-dna a:hover { text-decoration: underline; }
.theme-facebook-dna input, .theme-facebook-dna select { background: var(--surface-2); border: 1px solid transparent; border-radius: var(--radius-pill); }
.theme-facebook-dna textarea { background: var(--surface-2); border: 1px solid transparent; border-radius: var(--radius-lg); }
.theme-facebook-dna input:focus-visible, .theme-facebook-dna textarea:focus-visible, .theme-facebook-dna select:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-facebook-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface-2); border: 1px solid var(--line); border-radius: 0.3rem; padding: 0.1em 0.45em; }
.theme-facebook-dna ::selection { background: oklch(0.88 0.05 261); }
.theme-facebook-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-facebook-dna ::-webkit-scrollbar-track { background: var(--bg); }
.theme-facebook-dna ::-webkit-scrollbar-thumb { background: oklch(0.78 0.005 258); border-radius: 5px; }
.theme-facebook-dna .label-caps { color: var(--fg-muted); font-weight: 700; }
.theme-facebook-dna .themed-border { border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow-1); }
.theme-facebook-dna button:active { transform: scale(0.96); } /* reaction press */

/* alt mode: FB dark — charcoal chrome, brighter #2D88FF-class blue */
.theme-facebook-dna.alt-mode {
  --bg: oklch(0.145 0.005 258.3);
  --surface: oklch(0.185 0.005 258.3);
  --surface-2: oklch(0.225 0.005 258.3);
  --accent: oklch(0.62 0.21 258);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-facebook-dna.alt-mode tbody tr:hover { background: oklch(1 0 0 / 5%); }
.theme-facebook-dna.alt-mode ::selection { background: oklch(0.45 0.10 258); }
.theme-facebook-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.4 0.005 258); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
